package app.noir.mobile;
import android.app.Activity;
import android.content.Intent;
import android.os.Bundle;
import android.widget.TextView;
import java.net.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.*;

public final class ShareToLogActivity extends Activity {
 final ExecutorService resolver=Executors.newSingleThreadExecutor();volatile HttpURLConnection connection;
 static final class Shared {String imdb="",title="",url="",providerId="";}
 static boolean supported(String host){if(host==null)return false;host=host.toLowerCase(Locale.ROOT);for(String domain:new String[]{"imdb.com","netflix.com","trakt.tv","letterboxd.com","themoviedb.org","tmdb.org"})if(host.equals(domain)||host.equals("www."+domain))return true;return false;}
 static Shared parse(String text,String subject){Shared s=new Shared();String raw=text==null?"":text.trim();Matcher imdb=Pattern.compile("(?i)\\btt\\d{5,12}\\b").matcher(raw);if(imdb.find())s.imdb=imdb.group().toLowerCase(Locale.ROOT);Matcher link=Pattern.compile("https?://[^\\s<>\"\\u200e\\u200f]+",Pattern.CASE_INSENSITIVE).matcher(raw);if(link.find()){String value=link.group().replaceAll("[).,]+$","");try{URI uri=new URI(value);if(supported(uri.getHost())){s.url=uri.getScheme().equalsIgnoreCase("http")?"https"+value.substring(4):value;String path=uri.getPath();String[] parts=path.split("/");for(int n=0;n<parts.length-1;n++)if(Arrays.asList("title","watch","film","movies","shows","movie","tv").contains(parts[n])){String id=parts[n+1];s.providerId=id;String slug=id.replaceFirst("^\\d+-","");if(!slug.matches("\\d+|tt\\d+"))s.title=slug.replace('-',' ');}}}catch(Exception ignored){}}
  String outside=raw.replaceAll("https?://[^\\s]+","").trim().replaceAll("^[\\s:–—-]+|[\\s:–—-]+$","");if(subject!=null&&!subject.trim().isEmpty())s.title=subject.trim();else if(s.title.isEmpty()&&!outside.isEmpty()&&!outside.matches("(?i)tt\\d+"))s.title=outside;s.title=s.title.replaceAll("(?i)^watch\\s+|\\s*[|·]\\s*(Netflix|IMDb|Trakt|Letterboxd|TMDB).*$","").trim();if(s.url.isEmpty()&&s.title.isEmpty()&&s.imdb.isEmpty()&&!raw.startsWith("http"))s.title=raw;return s;}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);Loc.use(NoirApp.data);Loc.apply(this);TextView label=new TextView(this);label.setText(Loc.t("Opening shared title…"));label.setTextColor(MainActivity.GOLD);label.setBackgroundColor(MainActivity.BLACK);label.setGravity(android.view.Gravity.CENTER);setContentView(label);CharSequence shared=getIntent().getCharSequenceExtra(Intent.EXTRA_TEXT);Shared s=parse(shared==null?"":shared.toString(),getIntent().getStringExtra(Intent.EXTRA_SUBJECT));if(s.imdb.isEmpty()&&s.title.isEmpty()&&!s.url.isEmpty())resolver.execute(()->{resolve(s);runOnUiThread(()->launch(s));});else launch(s);}
 void resolve(Shared s){try{String url=s.url;for(int n=0;n<4&&!Thread.currentThread().isInterrupted();n++){URI uri=new URI(url);if(!supported(uri.getHost())||!"https".equalsIgnoreCase(uri.getScheme())||uri.getUserInfo()!=null||uri.getPort()!=-1&&uri.getPort()!=443)return;HttpURLConnection c=(HttpURLConnection)uri.toURL().openConnection();connection=c;c.setConnectTimeout(4500);c.setReadTimeout(4500);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Mozilla/5.0 NoirShare/1.0");try{int code=c.getResponseCode();if(code>=300&&code<400){String location=c.getHeaderField("Location");if(location==null)return;url=uri.resolve(location).toString();continue;}if(code!=200)return;StringBuilder html=new StringBuilder();try(Reader in=new InputStreamReader(c.getInputStream(),java.nio.charset.StandardCharsets.UTF_8)){char[] b=new char[4096];int read;while(html.length()<262144&&(read=in.read(b))!=-1)html.append(b,0,read);}Matcher meta=Pattern.compile("<meta\\b[^>]*>",Pattern.CASE_INSENSITIVE).matcher(html);while(meta.find()){String tag=meta.group();if(!tag.matches("(?is).*?(?:property|name)\\s*=\\s*['\"](?:og:title|twitter:title)['\"].*"))continue;Matcher content=Pattern.compile("content\\s*=\\s*(['\"])(.*?)\\1",Pattern.CASE_INSENSITIVE|Pattern.DOTALL).matcher(tag);if(content.find()){s.title=clean(content.group(2));break;}}if(s.title.isEmpty()){Matcher title=Pattern.compile("<title[^>]*>(.*?)</title>",Pattern.CASE_INSENSITIVE|Pattern.DOTALL).matcher(html);if(title.find())s.title=clean(title.group(1));}return;}finally{c.disconnect();connection=null;}}}catch(Exception ignored){}}
 static String clean(String value){return value.replace("&amp;","&").replace("&#39;","'").replace("&quot;","\"").replaceAll("(?i)^watch\\s+|\\s*[|·]\\s*(Netflix|IMDb|Trakt|Letterboxd|TMDB).*$","").trim();}
 void launch(Shared s){if(isFinishing()||isDestroyed())return;startActivity(new Intent(this,LogActivity.class).putExtra("query",s.title.isEmpty()&&s.imdb.isEmpty()?s.providerId:s.title).putExtra("imdb",s.imdb).putExtra("sharedProviderId",s.providerId).putExtra("shareToLog",true));finish();}
 @Override protected void onDestroy(){HttpURLConnection c=connection;if(c!=null)c.disconnect();resolver.shutdownNow();super.onDestroy();}
}
